    bins = np.asarray(bins)
    # If edges are None or empty, return the sum of bins
    if edges is None or len(edges) == 0:
        return np.sum(bins)
    # Handle 1‑D edges
    edges_arr = np.asarray(edges)
    if edges_arr.ndim == 1:
        widths = np.diff(edges_arr)
        return np.sum(bins * widths)
    # Multi‑dimensional histogram: edges is a sequence of 1‑D edge arrays
    if isinstance(edges, (list, tuple)):
        widths = [np.diff(e) for e in edges]
