                    for cf in value[version]:
                        if isinstance(cf, (list, set)):
                            files.update(cf)
                        else:
                            files.add(cf)

            # Case 2: value is a list of entry dicts.
            elif isinstance(value, list):
                for entry in value:
                    if isinstance(entry, dict):
                        if entry.get("version") == version:
                            cf = entry.get("content_file")
                            if isinstance(cf, (list, set)):
                                files.update(cf)
                            else:
