def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    import click
    try:
        from borgmatic import cli as borg_cli
    except Exception:
        return ""
    # Assume the main command is the `cli` attribute of borgmatic.cli module
    cmd = borg_cli.cli
    # Gather all parameters from the command
    params = sorted(
        cmd.get_params(click.Context(cmd)),
        key=lambda p: ("option", "argument").index(p.param_type_name)
    )
    # Build a list of tokens to offer for completion
    tokens = []

    def longest_opt(opts):
        return max(opts, key=len)

    for p in params:
        if p.param_type_name == "option":
            opt = longest_opt(p.opts)
            if p.is_flag:
                tokens.append(opt)
            else:
                tokens.append(f"{opt}=")
        elif p.param_type_name == "argument":
            # Arguments are positional; show the help text if available
            help_text = p.help or ""
            # Use the longest name as a placeholder for argument completion
            arg_name = longest_opt(p.opts) if p.opts else p.name
            tokens.append(f"{arg_name} ({help_text})")
    # Build the bash completion function script
    opts_string = " ".join(tokens)
    script = f'''_borgmatic()
{{
    local cur prev opts
    COMPREPLY=()
    cur="{{COMP_WORDS[COMP_CWORD]}}"
    opts="{opts_string}"
    COMPREPLY=( $(compgen -W "$opts" -- "$cur") )
}}
complete -F _borgmatic borgmatic'''
    return script

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_namespaces = {}
    # Keep track of the unknown arguments for each parser
    remaining_by_parser = {}
    args_list = list(unparsed_arguments)

    # Parse each subparser independently
    for name, parser in subparsers.items():
        try:
            ns, remaining = parser.parse_known_args(args_list)
        except SystemExit:
            # In case a subparser exits on parse error, treat all arguments as unknown
            ns, remaining = argparse.Namespace(), args_list
        parsed_namespaces[name] = ns
        remaining_by_parser[name] = remaining

    # If there are no subparsers, all arguments are considered remaining
    if not subparsers:
        return parsed_namespaces, args_list

    # Determine arguments not claimed by any subparser: those that appear in all remaining lists
    unclaimed = []
    for arg in args_list:
        if all(arg in remaining_by_parser[name] for name in remaining_by_parser):
            unclaimed.append(arg)

    return parsed_namespaces, unclaimed

