def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    from pathlib import Path
    import os

    # Determine the name for the extracted repository directory
    if filename is None:
        name = Path(archive_path).name
        # Strip common archive extensions
        for ext in ('.tar.gz', '.tgz', '.tar.bz2', '.tbz2',
                    '.tar.xz', '.txz', '.tar', '.gz', '.bz2', '.xz', '.zip'):
            if name.lower().endswith(ext):
                name = name[: -len(ext)]
                break
        else:
            # Fallback to stem (removes last suffix)
            name = Path(archive_path).stem
    else:
        name = filename

    dest_dir = Path(tmp_path) / name
    dest_dir.mkdir(parents=True, exist_ok=False)

    # Extract the archive using appropriate command
    if archive_path.lower().endswith(('.tar.gz', '.tgz')):
        subprocess.check_call(['tar', '-xzf', archive_path, '-C', str(dest_dir)])
    elif archive_path.lower().endswith(('.tar.bz2', '.tbz2')):
        subprocess.check_call(['tar', '-xjf', archive_path, '-C', str(dest_dir)])
    elif archive_path.lower().endswith(('.tar.xz', '.txz')):
        subprocess.check_call(['tar', '-xJf', archive_path, '-C', str(dest_dir)])
    elif archive_path.lower().endswith('.zip'):
        subprocess.check_call(['unzip', '-q', archive_path, '-d', str(dest_dir)])
    else:
        # Default to tar extraction (works for .tar and unknown extensions)
        subprocess.check_call(['tar', '-xf', archive_path, '-C', str(dest_dir)])

    return f'file://{dest_dir.resolve()}')

