    if not isinstance(frequency, str):
        raise ValueError("frequency must be a string")
    parts = frequency.strip().split()
    if len(parts) != 2:
        raise ValueError(f"cannot parse frequency '{frequency}'")
    value_part, unit_part = parts
    try:
        value = int(value_part)
    except ValueError:
        raise ValueError(f"invalid numeric value '{value_part}' in frequency '{frequency}'")
    unit = unit_part.lower()
    if unit in ("days", "day", "d"):
        return datetime.timedelta(days=value)
    if unit in ("weeks", "week", "w"):
        return datetime.timedelta(weeks=value)
    if unit in ("hours", "hour", "h"):
        return datetime.timedelta(hours=value)
    if unit in ("minutes", "minute", "m"):
        return datetime.timedelta(minutes=value)
    if unit in ("seconds", "second", "s"):
        return datetime.timedelta(seconds=value)
    raise ValueError(f"unknown time unit '{unit}' in frequency '{frequency}'")

