def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    # Build child -> set(parents) mapping
    child_parents: Dict["Node", Set["Node"]] = {}
    all_nodes: Set["Node"] = set()
    for subj, _, obj in graph.triples((None, prop, None)):
        all_nodes.add(subj)
        all_nodes.add(obj)
        child_parents.setdefault(subj, set()).add(obj)

    # Determine starting set of candidate roots
    if roots is None:
        # consider all nodes that appear as child in a triple
        start_nodes = set(child_parents.keys())
    else:
        start_nodes = set(roots)

    # Collect nodes that have no parents reachable from start_nodes
    result: Set["Node"] = set()
    visited: Set["Node"] = set()

    stack = list(start_nodes)
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        parents = child_parents.get(node, set())
        if not parents:
            result.add(node)
        else:
            # Explore all parent paths (to handle multiple parents / cycles)
            for p in parents:
                if p not in visited:
                    stack.append(p)

    # If roots was supplied, also include any of those that are true roots
    if roots is not None:
        for node in roots:
            if node not in child_parents or not child_parents[node]:
                result.add(node)

    return result

